contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint ts) public payable {
        require(address(this).balance >= amount);

        // Ensure a non-decreasing timestamp baseline; the very first call also has pastBlockTime == 0.
        bool firstReverted;
        uint ts2 = ts;
        try c.fallback{value: amount}() { firstReverted = false; } catch { firstReverted = true; }

        uint beforeBalance = address(c).balance;

        bool secondReverted;
        try c.fallback{value: amount}() { secondReverted = false; } catch { secondReverted = true; }

        uint afterBalance = address(c).balance;

        // General rule: fallback reverts exactly when the sent amount is not 10 ether.
        // When it does not revert, the call must have increased c's Ether balance by amount
        // (the self-destruct branch could only decrease it, so we assert the guard form).
        assert((secondReverted && amount != 10 ether) || (!secondReverted && amount == 10 ether));
    }

    receive() external payable {}
}

