contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient balance");

        // Seed pastBlockTime with a successful call
        (bool okSeed, ) = address(c).call{value: 10 ether}("");
        require(okSeed, "seed call failed");
        uint pastBefore = c.pastBlockTime();

        bool reverted;
        (bool ok, ) = address(c).call{value: amount}("");
        if (ok) {
            reverted = false;
        } else {
            reverted = true;
        }

        // The rule: success iff exactly 10 ether is sent and the timestamp advances.
        // Since block.timestamp can't be controlled, the deciding observable condition
        // is: if amount != 10 ether, it must revert; if amount == 10 ether and the
        // timestamp advanced past pastBefore, it must succeed; otherwise it must revert.
        uint pastAfter = c.pastBlockTime();
        bool timestampAdvanced = pastAfter > pastBefore;

        if (amount != 10 ether) {
            assert(reverted);
        } else if (timestampAdvanced) {
            assert(!reverted);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

