contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, uint256 bgap) public payable {
        require(amount == 10 ether, "amount must be 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        uint256 beforeTime = c.pastBlockTime();
        uint256 beforeBal = address(c).balance;
        uint256 beforeThisBal = address(this).balance;

        // The fallback rejects a timestamp <= the stored pastBlockTime.
        // By choosing a guaranteed-larger timestamp for the happy-path call,
        // we require the call to succeed and then check the state-change rule.
        // The revert side is checked by forcing a non-increasing timestamp again.
        bool firstReverted;
        try c.fallback{value: amount}() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        // The three observable consequences of a successful fallback:
        // 1. The call does not revert.
        // 2. pastBlockTime becomes the current block timestamp, which is > beforeTime.
        // 3. The contract balance grows by exactly the sent amount (no transfers in general calls)
        //    when the block number condition does not trigger.
        assert(firstReverted == (amount != 10 ether || block.timestamp <= beforeTime));
    }

    receive() external payable {}
}

