contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint valueSent, uint timeHint) public payable {
        require(address(this).balance >= valueSent);
        require(timeHint > 0);

        // Send a donation to c so address(c).balance can change/be non-zero independently of this call.
        (bool preOk, ) = address(c).call{value: 1 wei}(abi.encodeWithSignature("donate()"));
        preOk;

        uint balanceBefore = address(c).balance;
        uint pastBefore = c.pastBlockTime();

        bool reverted;
        try c.call{value: valueSent}(abi.encodeWithSignature("")) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = address(c).balance;
        uint pastAfter = c.pastBlockTime();

        // General rule:
        // - With value != 10 ether, the fallback must revert.
        // - With value == 10 ether, it must not revert due to the value condition,
        //   and if it completes, pastBlockTime is at least its previous value,
        //   and any balance decrease is exactly the payout to the test contract (when the payout branch fires).
        if (valueSent != 10 ether) {
            assert(reverted);
        } else {
            assert(!reverted);
            assert(pastAfter >= pastBefore);
            // If balance decreased, the test contract must have received exactly that much.
            assert(
                balanceAfter == balanceBefore ||
                address(this).balance == valueSent + (balanceBefore - balanceAfter)
            );
        }
    }

    fallback() external payable {}
}

