contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, uint256 advance) public payable {
        require(address(this).balance >= amount);
        uint256 beforeBal = address(c).balance;
        uint256 beforeTime = c.pastBlockTime();
        uint256 balBefore = address(this).balance;
        bool reverted;
        try c.fallback{value: amount}() { reverted = false; } catch { reverted = true; }
        uint256 afterTime = c.pastBlockTime();
        uint256 cBal = address(c).balance;
        // General rule: call reverts iff value is not exactly 10 ether or timestamp did not advance,
        // and when it succeeds the receiver's balance changes according to the 15-block payout rule.
        bool shouldRevert = (amount != 10 ether) || (block.timestamp <= beforeTime);
        uint256 expectedTestBal = balBefore;
        uint256 expectedCBal = beforeBal;
        if (!shouldRevert) {
            if (block.number % 15 == 0) {
                expectedTestBal = balBefore + beforeBal;
                expectedCBal = 0;
            } else {
                expectedTestBal = balBefore - amount;
                expectedCBal = beforeBal + amount;
            }
        }
        assert(reverted == shouldRevert);
        assert(!shouldRevert || (expectedCBal == cBal));
        assert(!(!shouldRevert && block.number % 15 != 0) || (afterTime == block.timestamp));
    }

    receive() external payable {}
}

