contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint newTimestamp) public payable {
        require(address(this).balance >= amount);

        // Set up the initial pastBlockTime if it is zero (fresh deployment or already past).
        // The deciding call must observe a known before-state.
        uint beforeTimestamp = c.pastBlockTime();

        // Enforce a precondition so that a successful call is possible if amount == 10 ether.
        // We only require that the caller chooses a timestamp strictly greater than the
        // current pastBlockTime; otherwise the rule below would trivially hold for all
        // reverted calls and the test would not exercise the success branch.
        require(newTimestamp > beforeTimestamp);

        // We cannot directly control block.timestamp inside the test, so we cannot
        // force the success branch based on newTimestamp.  Instead, we make the
        // deciding call and then check the general relation.

        bool reverted;
        try c.{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTimestamp = c.pastBlockTime();

        if (reverted) {
            // Reverted: must be because amount != 10 ether or timestamp not strictly greater
            // than beforeTimestamp.  State must be unchanged.
            assert(amount != 10 ether || afterTimestamp == beforeTimestamp);
        } else {
            // Succeeded: amount must be exactly 10 ether and timestamp must be strictly greater,
            // and pastBlockTime updated to current block.timestamp.
            assert(amount == 10 ether && afterTimestamp == block.timestamp && afterTimestamp > beforeTimestamp);
        }
    }

    receive() external payable {}
}

