        uint beforeBlockTime = c.pastBlockTime();
        require(ts > beforeBlockTime);

        bool reverted;
        address(c).call{value: amount}(abi.encodeWithSignature(""));
        // determine revert outcome through balance/state observation
        uint afterBalance = address(c).balance;
        uint afterBlockTime = c.pastBlockTime();

        // cannot directly observe revert; infer from state changes
        bool success = (afterBalance == beforeBalance + amount) || (afterBalance == 0 && beforeBalance + amount > 0);
        // success is true iff call did not revert and msg.value was 10 ether and ts > pastBlockTime
        // But we need deterministic check: use low-level call and decode revert

        // Instead, do a clean try/catch via external call helper is not allowed; use raw call and inspect returndatasize
        // The following assert is the general rule: if amount != 10 ether, call must revert (balance unchanged and timestamp unchanged)

        assert(
            amount != 10 ether ?
                (afterBalance == beforeBalance && afterBlockTime == beforeBlockTime) :
                (ts > beforeBlockTime ?
                    (afterBalance == beforeBalance + amount && afterBlockTime == ts) :
                    (afterBalance == beforeBalance && afterBlockTime == beforeBlockTime)
                )
        );
    }

    receive() external payable {}
}

